from collections import defaultdict, deque, Counter

def comps(g,bg):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if g[r][c]==bg or (r,c) in seen: continue
   col=g[r][c]; q=deque([(r,c)]); seen.add((r,c)); pts=[]
   while q:
    y,x=q.popleft(); pts.append((y,x))
    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
     z=(y+dy,x+dx)
     if 0<=z[0]<h and 0<=z[1]<w and z not in seen and g[z[0]][z[1]]==col:
      seen.add(z);q.append(z)
   y0=min(y for y,x in pts); x0=min(x for y,x in pts)
   shp=frozenset((y-y0,x-x0) for y,x in pts)
   out.append((col,pts,shp))
 return out
