def repeated_groups(g):
 bg=Counter(v for row in g for v in row).most_common(1)[0][0]
 objs=comps(g,bg); groups=defaultdict(list)
 for color,pts,shape in objs: groups[shape].append((color,pts))
 return bg,[(shape,members) for shape,members in groups.items() if len(members)>1],objs
